"""base64: the four functions the engine serves, and the rest built on them.

The core engine refuses ``import base64`` outright.  The wider variant
serves exactly four names -- ``b64encode``, ``b64decode``,
``urlsafe_b64encode``, ``urlsafe_b64decode`` -- and even those only in
their plain form: ``b64encode(s, altchars=...)`` refuses, and
``b64decode(s, validate=True)`` refuses because a truthy ``validate``
selects binascii's strict mode, whose every rejection is a
``binascii.Error`` message the engine does not write.

Everything else in the module refuses as ``module-attr``:
``standard_b64encode``, ``standard_b64decode``, ``b32encode``,
``b32decode``, ``b32hexencode``, ``b32hexdecode``, ``b16encode``,
``b16decode``, ``encodebytes``, ``decodebytes``, ``a85``/``b85``.

So this unit is the rest of RFC 4648 written on top of the part that
works.  ``b64encode``'s output is taken from the engine and the
``altchars`` substitution is applied afterwards, one byte at a time --
which is what ``bytes.maketrans`` does, and unlike two chained
``.replace()`` calls it is *simultaneous*, so an ``altchars`` of
``b'/+'`` swaps rather than collapses.  Base32 and base16 are written
out from the bit layout, because there is nothing underneath them to
lean on.

The layouts, since the whole point of this file is that they are
reproduced from the spec rather than remembered:

  * **base64** -- 3 bytes -> 4 characters of 6 bits, alphabet ``A-Za-z0-9+/``,
    padded to a multiple of 4 with ``=``.  urlsafe swaps ``+/`` for ``-_``.
  * **base32** -- 5 bytes -> 8 characters of 5 bits, alphabet
    ``A-Z2-7``, padded to a multiple of 8.  A short final quantum leaves
    1, 3, 4 or 6 pad characters and never 2, 5 or 7, which is why
    ``b32decode`` rejects any other pad count as ``Incorrect padding``.
    base32hex is the same layout over ``0-9A-V``, whose ordering makes
    the encoding sort the same way the input does.
  * **base16** -- 1 byte -> 2 upper-case hex digits, never padded.

Three ``b32decode`` details that are easy to get wrong and are pinned
below: ``casefold`` upper-cases before decoding; ``map01`` maps the
digit ``0`` to ``O`` *and* the digit ``1`` to whichever of ``I`` or ``L``
is passed, so passing ``map01`` is what makes ``0`` and ``1`` legal at
all; and the pad count is validated *after* the quanta are decoded, so a
string of the right length with a wrong pad count still reports
``Incorrect padding`` rather than ``Non-base32 digit found``.

Verification, run 2026-09-16: besides the case list, a randomised
sweep compared all six encoders and all six decoders against the real
module on 4,000 payloads of up to 70 bytes plus 4,000 random
``altchars`` pairs, and fuzzed the four decoders with 20,000 junk
strings drawn from the alphabet, the pad character, lower case, digits,
a non-ASCII byte, a space and a newline -- comparing the decoded value
*or* the exception message.  104,000 checks, 0 divergences.

Deliberate divergences, all forced by the subset:

  * **Exception class, not message.**  CPython raises ``binascii.Error``.
    That class *is* a subclass of ``ValueError``, so ``except ValueError``
    catches both, and every message here is CPython's verbatim:
    ``Incorrect padding``, ``Non-base32 digit found``,
    ``Non-base16 digit found``, ``Odd-length string``,
    ``string argument should contain only ASCII characters``.
  * **No ``validate=True``.**  ``b64decode`` here is the lenient mode
    only: characters outside the alphabet are discarded before decoding,
    which is what the engine's ``b64decode`` does and what CPython does
    with ``validate=False``.  Strict mode is not faked.
  * ``b16encode`` is built from ``bytes.hex()`` rather than
    ``binascii.hexlify``; ``bytes.fromhex`` is refused, so ``b16decode``
    converts nibble by nibble.
  * ``bytes.upper()``, ``bytes.translate`` and ``bytearray`` are all
    outside the subset, so every decoder works on a list of integers and
    calls ``bytes(...)`` once at the end.
"""
# fills: base64.standard_b64encode, base64.standard_b64decode, base64.b32encode, base64.b32decode, base64.b32hexencode, base64.b32hexdecode, base64.b16encode, base64.b16decode, base64.encodebytes, base64.decodebytes
# reference: base64

import base64

_B32_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
_B32HEX_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUV"


def _as_byte_list(data):
    """CPython's _bytes_from_decode_data, as a list of ints.

    A str argument must be pure ASCII; bytes pass through unchanged.
    """
    if isinstance(data, str):
        out = []
        for ch in data:
            code = ord(ch)
            if code > 127:
                raise ValueError(
                    "string argument should contain only ASCII characters")
            out.append(code)
        return out
    return list(data)


def _upper_byte(code):
    if 97 <= code <= 122:
        return code - 32
    return code


def _substitute(values, frm, to):
    """Simultaneous single-byte substitution -- bytes.maketrans, by hand."""
    out = []
    for code in values:
        if code == frm[0]:
            out.append(to[0])
        elif code == frm[1]:
            out.append(to[1])
        else:
            out.append(code)
    return out


def b64encode(data, altchars=None):
    """Base64 with an optional two-byte replacement for `+` and `/`."""
    encoded = base64.b64encode(data)
    if altchars is None:
        return encoded
    alt = _as_byte_list(altchars)
    return bytes(_substitute(list(encoded), [43, 47], alt))


def b64decode(data, altchars=None):
    """Base64, lenient: characters outside the alphabet are discarded."""
    values = _as_byte_list(data)
    if altchars is not None:
        alt = _as_byte_list(altchars)
        values = _substitute(values, alt, [43, 47])
    return base64.b64decode(bytes(values))


def standard_b64encode(data):
    """base64.standard_b64encode -- b64encode with no altchars."""
    return b64encode(data)


def standard_b64decode(data):
    """base64.standard_b64decode -- b64decode with no altchars."""
    return b64decode(data)


def urlsafe_b64encode(data):
    """Base64 over the URL and filename safe alphabet: `-` and `_`."""
    return b64encode(data, b"-_")


def urlsafe_b64decode(data):
    """The inverse of urlsafe_b64encode."""
    return b64decode(data, b"-_")


def encodebytes(data):
    """MIME base64: 57 input bytes per line, each line ending in `\\n`."""
    pieces = []
    for i in range(0, len(data), 57):
        pieces.append(base64.b64encode(data[i:i + 57]))
        pieces.append(b"\n")
    return b"".join(pieces)


def decodebytes(data):
    """The inverse of encodebytes; newlines are simply not in the alphabet."""
    return b64decode(data)


def _b32encode(alphabet, data):
    leftover = len(data) % 5
    if leftover:
        data = data + bytes(5 - leftover)
    out = []
    for i in range(0, len(data), 5):
        acc = 0
        for byte in data[i:i + 5]:
            acc = (acc << 8) + byte
        shift = 35
        while shift >= 0:
            out.append(alphabet[(acc >> shift) % 32])
            shift = shift - 5
    encoded = "".join(out)
    # A short final quantum leaves 1, 3, 4 or 6 pad characters.
    if leftover == 1:
        encoded = encoded[:-6] + "======"
    elif leftover == 2:
        encoded = encoded[:-4] + "===="
    elif leftover == 3:
        encoded = encoded[:-3] + "==="
    elif leftover == 4:
        encoded = encoded[:-1] + "="
    return encoded.encode()


def _b32decode(alphabet, data, casefold=False, map01=None):
    values = _as_byte_list(data)
    if len(values) % 8:
        raise ValueError("Incorrect padding")
    if map01 is not None:
        mapped = _as_byte_list(map01)
        if len(mapped) != 1:
            raise ValueError("map01 must be a single character")
        # RFC 4648 section 2.4: 0 reads as O, and 1 as either I or L.
        values = _substitute(values, [48, 49], [79, mapped[0]])
    if casefold:
        values = [_upper_byte(code) for code in values]
    reverse = {}
    for index in range(len(alphabet)):
        reverse[ord(alphabet[index])] = index
    total = len(values)
    end = total
    while end > 0 and values[end - 1] == 61:
        end = end - 1
    body = values[:end]
    padchars = total - end
    decoded = []
    acc = 0
    for i in range(0, len(body), 8):
        acc = 0
        for code in body[i:i + 8]:
            if code not in reverse:
                raise ValueError("Non-base32 digit found")
            acc = (acc << 5) + reverse[code]
        for shift in (32, 24, 16, 8, 0):
            decoded.append((acc >> shift) % 256)
    # The pad count is checked here, after the quanta, exactly as CPython
    # checks it -- the order decides which of the two errors you see.
    if total % 8 or padchars not in (0, 1, 3, 4, 6):
        raise ValueError("Incorrect padding")
    if padchars and decoded:
        acc = acc << (5 * padchars)
        last = []
        for shift in (32, 24, 16, 8, 0):
            last.append((acc >> shift) % 256)
        leftover = (43 - 5 * padchars) // 8
        decoded = decoded[:-5] + last[:leftover]
    return bytes(decoded)


def b32encode(data):
    """RFC 4648 base32, alphabet A-Z and 2-7."""
    return _b32encode(_B32_ALPHABET, data)


def b32decode(data, casefold=False, map01=None):
    """RFC 4648 base32, decoded."""
    return _b32decode(_B32_ALPHABET, data, casefold, map01)


def b32hexencode(data):
    """RFC 4648 base32hex ("extended hex"), alphabet 0-9 and A-V."""
    return _b32encode(_B32HEX_ALPHABET, data)


def b32hexdecode(data, casefold=False):
    """RFC 4648 base32hex, decoded.  No map01: 0 and 1 are real digits here."""
    return _b32decode(_B32HEX_ALPHABET, data, casefold, None)


def b16encode(data):
    """RFC 4648 base16: upper-case hex, never padded."""
    return data.hex().upper().encode()


def _hexval(code):
    if 48 <= code <= 57:
        return code - 48
    return code - 55


def b16decode(data, casefold=False):
    """RFC 4648 base16, decoded.  Lower case only with casefold=True."""
    values = _as_byte_list(data)
    if casefold:
        values = [_upper_byte(code) for code in values]
    for code in values:
        if not ((48 <= code <= 57) or (65 <= code <= 70)):
            raise ValueError("Non-base16 digit found")
    # The digit check runs first, so a bad character in an odd-length
    # string reports the bad character and not the length.
    if len(values) % 2:
        raise ValueError("Odd-length string")
    out = []
    for i in range(0, len(values), 2):
        out.append(_hexval(values[i]) * 16 + _hexval(values[i + 1]))
    return bytes(out)


def _message(fn, *args):
    """Run fn(*args) and return its ValueError message, or the value."""
    try:
        return fn(*args)
    except ValueError as exc:
        return "ValueError: " + str(exc)

"""bisect.bisect_left / bisect_right / insort_left / insort_right.

A direct port of CPython's Lib/bisect.py, which is also what the C
accelerator ``_bisect`` computes: the midpoint is ``(lo + hi) // 2`` and
the comparison is always ``<``, never ``<=`` or ``>``, so the result
matches ``list.sort`` and ``heapq`` on any type that only defines
``__lt__``.  The two halves differ in exactly one place:

  * ``bisect_left`` tests ``a[mid] < x`` -- it lands BEFORE an equal run,
    so ``a[:i]`` is everything strictly less than `x`.
  * ``bisect_right`` tests ``x < a[mid]`` -- it lands AFTER an equal run,
    so ``a[:i]`` is everything less than or equal to `x`.

On a list with no element equal to `x` the two agree; the difference is
only ever visible on duplicates, which is why every duplicate case below
prints both.

``lo`` is validated (``ValueError('lo must be non-negative')``) and is NOT
clamped to ``len(a)``: ``bisect_right([1, 2, 3], 2, 5)`` is 5, because the
loop never runs.  ``hi`` defaults to ``len(a)``.

DIVERGENCE, deliberate, in the SIGNATURE only: CPython declares
``key`` keyword-only (``def bisect_left(a, x, lo=0, hi=None, *, key=None)``)
and a keyword-only parameter is a refusal on both engines, so `key` is an
ordinary fifth parameter here.  Every call CPython accepts, these accept,
with the same answer; these additionally accept `key` positionally, which
CPython rejects.  No case below passes `key` positionally.

Not covered, and not exercised: ``hi`` outside ``0 <= hi <= len(a)``.  The
documented contract does not allow it, and CPython's C accelerator answers
differently from its own pure-Python source there -- ``hi=-1`` is an
argument-clinic sentinel meaning ``len(a)`` in the C version and an empty
range in the Python one.  A unit must not pin a quirk its reference
implementation disagrees with itself about.
"""
# fills: bisect.bisect_left, bisect.bisect_right, bisect.insort_left, bisect.insort_right, bisect.bisect, bisect.insort
# reference: bisect


def bisect_left(a, x, lo=0, hi=None, key=None):
    """Index where `x` goes in sorted `a`, before any equal element."""
    if lo < 0:
        raise ValueError("lo must be non-negative")
    if hi is None:
        hi = len(a)
    if key is None:
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < x:
                lo = mid + 1
            else:
                hi = mid
    else:
        while lo < hi:
            mid = (lo + hi) // 2
            if key(a[mid]) < x:
                lo = mid + 1
            else:
                hi = mid
    return lo


def bisect_right(a, x, lo=0, hi=None, key=None):
    """Index where `x` goes in sorted `a`, after any equal element."""
    if lo < 0:
        raise ValueError("lo must be non-negative")
    if hi is None:
        hi = len(a)
    if key is None:
        while lo < hi:
            mid = (lo + hi) // 2
            if x < a[mid]:
                hi = mid
            else:
                lo = mid + 1
    else:
        while lo < hi:
            mid = (lo + hi) // 2
            if x < key(a[mid]):
                hi = mid
            else:
                lo = mid + 1
    return lo


def insort_left(a, x, lo=0, hi=None, key=None):
    """Insert `x` into sorted `a`, before any element equal to it."""
    if key is None:
        at = bisect_left(a, x, lo, hi)
    else:
        at = bisect_left(a, key(x), lo, hi, key)
    a.insert(at, x)


def insort_right(a, x, lo=0, hi=None, key=None):
    """Insert `x` into sorted `a`, after any element equal to it."""
    if key is None:
        at = bisect_right(a, x, lo, hi)
    else:
        at = bisect_right(a, key(x), lo, hi, key)
    a.insert(at, x)


# CPython's own aliases, at the bottom of Lib/bisect.py.
bisect = bisect_right
insort = insort_right

def _insorted_left(seq, x, lo=0, hi=None, key=None):
    """Copy `seq`, insort_left `x` into the copy, return the copy.

    The cases print values, so the mutation needs a return; the copy also
    keeps each case independent of the one before it.
    """
    out = seq[:]
    insort_left(out, x, lo, hi, key=key)
    return out


def _insorted_right(seq, x, lo=0, hi=None, key=None):
    """Copy `seq`, insort_right `x` into the copy, return the copy."""
    out = seq[:]
    insort_right(out, x, lo, hi, key=key)
    return out


def _insort_returns(seq, x):
    """The RETURN VALUE of insort_right, which is always None."""
    return insort_right(seq[:], x)


def _doubles(n):
    """[0, 2, 4, ...] with `n` elements -- a big sorted list for the cases."""
    return [i * 2 for i in range(n)]


def _first_word(pair):
    return pair[0]

"""collections.Counter's refused half, and defaultdict-shaped grouping.

The core engine refuses ``import collections`` outright.  The wider
variant serves the module, but only part of ``Counter``: construction
from an iterable or a mapping, ``c[k]``, ``k in c``, ``len``, ``del``,
``.items()``, ``.keys()``, ``.values()``, ``.get()``, ``.copy()``,
``.update()``, ``.most_common()`` and ``repr``.  It refuses
``Counter.elements``, ``Counter.total``, ``Counter.subtract`` and every
multiset operator -- ``c1 + c2``, ``c1 - c2``, ``c1 | c2``, ``c1 & c2``,
``+c``, ``-c`` -- and it refuses ``defaultdict(lambda: ...)``.

So this unit is written the way Counter code has to be written to run
here: **the refused constructs never appear**.  Not one of the helpers
below calls ``.elements()``, ``.total()`` or ``.subtract()``, adds two
Counters, or hands ``defaultdict`` a lambda.  Each of those behaviours
is instead built out of the primitives the engine does serve, ported
from CPython 3.11's ``Lib/collections/__init__.py``:

  * ``most_common(c, n)`` -- CPython uses ``sorted(..., reverse=True)``
    when ``n`` is None and ``heapq.nlargest`` otherwise.  There is no
    ``heapq`` here, and none is needed: ``nlargest`` is documented as
    equivalent to ``sorted(iterable, key=key, reverse=True)[:n]`` and is
    stable in the same way, so one stable sort covers both.  Ties keep
    **first-insertion order**, which is the detail worth pinning, and
    ``n <= 0`` gives the empty list rather than a slice from the end.
  * ``elements(c)`` -- each key repeated by its count, in insertion
    order, skipping counts that are zero or negative.
  * ``total(c)`` -- the sum of the counts, negatives included.
  * ``subtract(c, other)`` -- in place, and unlike ``-`` it is allowed
    to drive counts to zero and below.
  * ``add`` / ``sub`` / ``union`` / ``intersection`` / ``positive`` /
    ``negative`` -- the multiset operators.  Their one shared rule is
    that the **output keeps only positive counts**, and their ordering
    rule is elements in the order first seen in the left operand, then
    in the right.  Both are ported exactly, including ``sub``'s odd but
    correct second loop, which lifts a *negative* count in the right
    operand into a positive count in the result.
  * ``group`` / ``group_by`` / ``tally_by`` -- ``defaultdict(list)`` and
    ``defaultdict(int)``.  A bare type as the factory is served; only a
    lambda factory is not, and nothing here needs one.

Two things about Counter that surprise people, both pinned below:

  * Reading a missing key returns ``0`` and **does not insert it**;
    augmenting one (``c[k] += 1``) does insert it.
  * A count reduced to zero stays in the counter.  It is still a key,
    it still shows up in ``most_common`` and ``repr``, and only
    ``elements`` and the operators drop it.

One deliberate divergence, forced by the subset and documented rather
than hidden: ``Counter.elements()`` returns an *iterator*; there are no
generators here, so ``elements`` returns a materialised list.  Every
case below compares it against ``list(real.elements())``, which is the
same sequence.  ``Counter.fromkeys`` is not covered: CPython defines it
only to raise ``NotImplementedError``, and the subset cannot raise that.
"""
# fills: collections.Counter.most_common, collections.Counter.elements, collections.Counter.total, collections.Counter.subtract, collections.Counter.__add__, collections.Counter.__sub__, collections.Counter.__or__, collections.Counter.__and__, collections.defaultdict
# reference: collections

import collections


def count(iterable):
    """Counter(iterable) -- tally the items of any iterable."""
    return collections.Counter(iterable)


def count_map(mapping):
    """Counter(mapping) -- take the counts straight from a dict."""
    return collections.Counter(mapping)


def most_common(counter, n=None):
    """The n most common (element, count) pairs, most common first.

    Stable: elements with equal counts keep the order they were first
    inserted in.  ``n is None`` lists everything; ``n <= 0`` is empty.
    """
    ordered = sorted(counter.items(), key=lambda kv: kv[1], reverse=True)
    if n is None:
        return ordered
    if n <= 0:
        return []
    return ordered[:n]


def elements(counter):
    """Each element repeated by its count; zero and negative are skipped.

    CPython returns an iterator; this returns the same sequence as a
    list, because the subset has no generators.
    """
    out = []
    for elem, cnt in counter.items():
        i = 0
        while i < cnt:
            out.append(elem)
            i = i + 1
    return out


def total(counter):
    """Sum of the counts, negatives included."""
    return sum(counter.values())


def update(counter, other):
    """Counter.update: add counts in, in place.  Accepts a mapping or an
    iterable.  Both inputs and outputs may hold zero and negative counts.
    """
    if isinstance(other, dict):
        for elem in other:
            counter[elem] = counter.get(elem, 0) + other[elem]
    else:
        for elem in other:
            counter[elem] = counter.get(elem, 0) + 1
    return counter


def subtract(counter, other):
    """Counter.subtract: take counts away, in place, below zero if need be."""
    if isinstance(other, dict):
        for elem in other:
            counter[elem] = counter.get(elem, 0) - other[elem]
    else:
        for elem in other:
            counter[elem] = counter.get(elem, 0) - 1
    return counter


def add(a, b):
    """a + b -- counts summed, only the positive results kept."""
    result = collections.Counter()
    for elem, cnt in a.items():
        newcount = cnt + b.get(elem, 0)
        if newcount > 0:
            result[elem] = newcount
    for elem, cnt in b.items():
        if elem not in a and cnt > 0:
            result[elem] = cnt
    return result


def sub(a, b):
    """a - b -- counts differenced, only the positive results kept.

    The second loop is not a typo: an element present only in ``b`` with
    a *negative* count contributes its magnitude to the result.
    """
    result = collections.Counter()
    for elem, cnt in a.items():
        newcount = cnt - b.get(elem, 0)
        if newcount > 0:
            result[elem] = newcount
    for elem, cnt in b.items():
        if elem not in a and cnt < 0:
            result[elem] = 0 - cnt
    return result


def union(a, b):
    """a | b -- the larger of the two counts, only the positive ones kept."""
    result = collections.Counter()
    for elem, cnt in a.items():
        other_count = b.get(elem, 0)
        if cnt < other_count:
            newcount = other_count
        else:
            newcount = cnt
        if newcount > 0:
            result[elem] = newcount
    for elem, cnt in b.items():
        if elem not in a and cnt > 0:
            result[elem] = cnt
    return result


def intersection(a, b):
    """a & b -- the smaller of the two counts, only the positive ones kept.

    There is no second loop: an element missing from ``a`` has count 0
    there, so the minimum can never be positive.
    """
    result = collections.Counter()
    for elem, cnt in a.items():
        other_count = b.get(elem, 0)
        if cnt < other_count:
            newcount = cnt
        else:
            newcount = other_count
        if newcount > 0:
            result[elem] = newcount
    return result


def positive(counter):
    """+c -- drop the zero and negative counts."""
    result = collections.Counter()
    for elem, cnt in counter.items():
        if cnt > 0:
            result[elem] = cnt
    return result


def negative(counter):
    """-c -- keep only the negative counts, with the sign flipped."""
    result = collections.Counter()
    for elem, cnt in counter.items():
        if cnt < 0:
            result[elem] = 0 - cnt
    return result


def group(pairs):
    """defaultdict(list): collect the values of (key, value) pairs by key."""
    groups = collections.defaultdict(list)
    for key, value in pairs:
        groups[key].append(value)
    return groups


def group_by(items, keyfunc):
    """defaultdict(list): bucket items by ``keyfunc(item)``, order kept."""
    groups = collections.defaultdict(list)
    for item in items:
        groups[keyfunc(item)].append(item)
    return groups


def tally_by(items, keyfunc):
    """defaultdict(int): count items by ``keyfunc(item)``."""
    tally = collections.defaultdict(int)
    for item in items:
        tally[keyfunc(item)] += 1
    return tally

